type Node = TextNode | InterpolationNode | BlockNode;

interface Position {
  offset: number;
  line: number;
  column: number;
}

interface TextNode {
  type: "text";
  value: string;
}

interface InterpolationNode {
  type: "interpolation";
  path: string;
  escaped: boolean;
  position: Position;
}

interface BlockNode {
  type: "block";
  kind: "if" | "each";
  path: string;
  body: Node[];
  alternate: Node[];
  position: Position;
}

interface Context {
  root: unknown;
  current: unknown;
  index: number | undefined;
}

interface ParseResult {
  nodes: Node[];
  endedBy: "else" | "close" | "eof";
}

class TemplateParser {
  private offset = 0;

  constructor(private readonly template: string) {}

  parse(): Node[] {
    return this.parseBody().nodes;
  }

  private parseBody(expectedClose?: "if" | "each", allowElse = false): ParseResult {
    const nodes: Node[] = [];

    while (this.offset < this.template.length) {
      const tagOffset = this.template.indexOf("{{", this.offset);
      if (tagOffset === -1) {
        nodes.push({ type: "text", value: this.template.slice(this.offset) });
        this.offset = this.template.length;
        break;
      }

      if (tagOffset > this.offset) {
        nodes.push({ type: "text", value: this.template.slice(this.offset, tagOffset) });
        this.offset = tagOffset;
      }

      const position = this.positionAt(this.offset);
      const triple = this.template.startsWith("{{{", this.offset);
      const openLength = triple ? 3 : 2;
      const close = triple ? "}}}" : "}}";
      const closeOffset = this.template.indexOf(close, this.offset + openLength);
      if (closeOffset === -1) {
        this.fail("Unclosed tag", position);
      }

      const content = this.template.slice(this.offset + openLength, closeOffset).trim();
      this.offset = closeOffset + close.length;

      if (triple) {
        if (!content) this.fail("Empty interpolation", position);
        nodes.push({ type: "interpolation", path: content, escaped: false, position });
        continue;
      }

      if (content.startsWith("!")) continue;

      if (content === "else") {
        if (!expectedClose) this.fail("'else' outside a block", position);
        if (!allowElse) this.fail("Duplicate 'else' in block", position);
        return { nodes, endedBy: "else" };
      }

      if (content.startsWith("/")) {
        const closeName = content.slice(1).trim();
        if (!expectedClose) this.fail(`Closing tag '/${closeName}' without an open block`, position);
        if (closeName !== expectedClose) {
          this.fail(`Mismatched closing tag: expected '/${expectedClose}', got '/${closeName}'`, position);
        }
        return { nodes, endedBy: "close" };
      }

      if (content.startsWith("#")) {
        nodes.push(this.parseBlock(content.slice(1).trim(), position));
        continue;
      }

      if (!content) this.fail("Empty interpolation", position);
      nodes.push({ type: "interpolation", path: content, escaped: true, position });
    }

    if (expectedClose) {
      this.fail(`Unclosed '#${expectedClose}' block`, this.positionAt(this.template.length));
    }
    return { nodes, endedBy: "eof" };
  }

  private parseBlock(source: string, position: Position): BlockNode {
    const match = /^(\S+)(?:\s+)([\s\S]+)$/.exec(source);
    const name = match?.[1];
    const path = match?.[2]?.trim();
    if (name !== "if" && name !== "each") {
      this.fail(`Unknown block '#${name ?? source}'`, position);
    }
    if (!path) this.fail(`Block '#${name}' requires a path`, position);

    const firstPart = this.parseBody(name, true);
    if (firstPart.endedBy === "else") {
      const secondPart = this.parseBody(name);
      return { type: "block", kind: name, path, body: firstPart.nodes, alternate: secondPart.nodes, position };
    }
    return { type: "block", kind: name, path, body: firstPart.nodes, alternate: [], position };
  }

  private positionAt(offset: number): Position {
    const before = this.template.slice(0, offset);
    const line = before.split("\n").length;
    const lastNewline = before.lastIndexOf("\n");
    return { offset, line, column: offset - lastNewline };
  }

  private fail(message: string, position: Position): never {
    throw new Error(`${message} at line ${position.line}, column ${position.column}`);
  }
}

/** Renders a Mini Template string using properties from the supplied root value. */
export function render(template: string, data: unknown): string {
  const tree = new TemplateParser(template).parse();
  return renderNodes(tree, { root: data, current: data, index: undefined });
}

function renderNodes(nodes: Node[], context: Context): string {
  return nodes.map((node) => {
    if (node.type === "text") return node.value;
    if (node.type === "interpolation") {
      const text = scalarText(resolvePath(node.path, context), node.position);
      return node.escaped ? escapeHtml(text) : text;
    }

    const value = resolvePath(node.path, context);
    if (node.kind === "if") {
      return renderNodes(isTemplateTruthy(value) ? node.body : node.alternate, context);
    }
    if (value === null || value === undefined) return renderNodes(node.alternate, context);
    if (!Array.isArray(value)) {
      throw renderError("'#each' requires an array", node.position);
    }
    if (value.length === 0) return renderNodes(node.alternate, context);
    return value.map((item, index) => renderNodes(node.body, { ...context, current: item, index })).join("");
  }).join("");
}

function resolvePath(path: string, context: Context): unknown {
  const trimmed = path.trim();
  if (trimmed === "this") return context.current;
  if (trimmed === "@index") return context.index;

  const fromCurrent = trimmed.startsWith("this.");
  const parts = (fromCurrent ? trimmed.slice(5) : trimmed).split(".");
  let value: unknown = fromCurrent ? context.current : context.root;
  for (const part of parts) {
    if (!part || value === null || value === undefined || (typeof value !== "object" && typeof value !== "function")) {
      return undefined;
    }
    if (!Object.prototype.hasOwnProperty.call(value, part)) return undefined;
    value = (value as Record<string, unknown>)[part];
  }
  return value;
}

function isTemplateTruthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return !(value === "" || value === 0 || value === false || value === null || value === undefined);
}

function scalarText(value: unknown, position: Position): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "object" || typeof value === "function") {
    throw renderError("Cannot render an object or function as text", position);
  }
  return String(value);
}

function renderError(message: string, position: Position): Error {
  return new Error(`${message} at line ${position.line}, column ${position.column}`);
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "\"": "&quot;",
    "'": "&#39;",
  })[character] as string);
}
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine";

describe("render", () => {
  test("escapes interpolated scalar values and preserves surrounding whitespace", () => {
    expect(render("  {{value}}\\n", { value: "&<>\\\"'" })).toBe("  &amp;&lt;&gt;&quot;&#39;\\n");
  });

  test("supports unescaped values, comments, and missing values", () => {
    expect(render("{{{html}}}{{! hidden }}:{{missing}}", { html: "<b>x</b>" })).toBe("<b>x</b>:");
  });

  test("renders nested if blocks with template truthiness", () => {
    expect(render("{{#if enabled}}a{{#if empty}}x{{else}}b{{/if}}{{else}}c{{/if}}", { enabled: true, empty: [] })).toBe("ab");
  });

  test("renders each context and falls back to root paths", () => {
    const template = "{{#each groups}}{{title}}:{{#each this}}{{@index}}={{this}};{{/each}}{{else}}none{{/each}}";
    expect(render(template, { title: "T", groups: [["a", "b"], ["c"]] })).toBe("T:0=a;1=b;T:0=c;");
  });

  test("uses each else for missing and empty arrays", () => {
    expect(render("{{#each items}}{{this}}{{else}}empty{{/each}}", { items: [] })).toBe("empty");
    expect(render("{{#each items}}{{this}}{{else}}empty{{/each}}", {})).toBe("empty");
  });

  test("rejects structural and non-scalar rendering errors with locations", () => {
    expect(() => render("{{#if ok}}{{/each}}", { ok: true })).toThrow(/line 1, column 11/);
    expect(() => render("{{else}}", {})).toThrow(/outside a block.*line 1, column 1/);
    expect(() => render("{{#wat x}}{{/wat}}", {})).toThrow(/Unknown block/);
    expect(() => render("{{value}}", { value: {} })).toThrow(/object or function.*line 1, column 1/);
  });
});
